from ntlib import *
m12 = (10**12-1)//27; m24 = (10**24-1)//27
# level-24 new primes and the (u,w)-box refinement ratios
for p in (73, 137, 99990001):
    phi = p-1
    o3, o7, o10 = order_fast(3,p,phi), order_fast(7,p,phi), order_fast(10,p,phi)
    s3 = o3//gcd(9900, o3)   # period of h_u -> 3^{U+9900 h_u} mod p
    s7 = o7//gcd(900, o7)    # period of h_w -> 7^{W+900 h_w} mod p
    # subgroup generated by A=3^9900, B=7^900 mod p
    A, B = pow(3,9900,p), pow(7,900,p)
    sub = set(); x = 1
    oA, oB = order_fast(A,p,phi), order_fast(B,p,phi)
    for i in range(oA):
        for j in range(oB): sub.add(x*pow(B,j,p))
        x = x*A%p
    print(f"p={p}: ord3={o3} ord7={o7} ord10={o10} | h_u period s3={s3}, h_w period s7={s7}, |<A,B>|={len(sub)} (of {phi})")
print("lambda24 = ord_m24(3)/9900 =", order_fast(3,m24,10**30)//9900 if False else None)
o3_24 = order_fast(3, m24, 2**40); o7_24 = order_fast(7, m24, 2**40)
print("ord_m24(3) =", o3_24, " lambda =", o3_24//9900)
print("ord_m24(7) =", o7_24, " mu      =", o7_24//900)
